// IMPORTANT: Array is circular, so also check LAST -> FIRST.
        // Example: [2,1,3,4] has 1 internal decrease (2->1)
        // but also a circular decrease (4->2), making it invalid.

solution:
class Solution {
public:
    bool check(vector<int>& nums) {
        int n = nums.size();

        // Edge case: n < 3 is always valid
        if (n < 3) {
            return true;
        }

        int dec = 0;

        for (int i = 1; i < n; i++) {
            if (nums[i] < nums[i - 1]) {
                dec++;
            }
        }

        // IMPORTANT: Array is circular, so also check LAST -> FIRST.
        // Example: [2,1,3,4] has 1 internal decrease (2->1)
        // but also a circular decrease (4->2), making it invalid.
        if (nums[n - 1] > nums[0]) {
            dec++;
        }

        // Sorted + rotated array can have at most ONE decrease.
        return dec < 2;
    }
};

class Solution {
public:
    int findClosestNumber(vector<int>& nums) {
        int ans = -100001;
        for (auto num : nums) {
            if ((abs(ans) > abs(num)) || (abs(ans) == abs(num) && ans < num)) {
                ans = num;
            }
        }
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {

        intervals.push_back(newInterval);

        sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b){
            if(a[0] == b[0]){
                return a[1] < b[1];
            }
            return a[0] < b[0];
        });

        vector<vector<int>> ans;
        int x = intervals[0][0];
        int y = intervals[0][1];

        for(auto inter: intervals){
            int x1 = inter[0];
            int y1 = inter[1];
            if(y < x1){
                ans.push_back({x,y});
                x = x1;
                y = y1;
            }else {
                x = min(x,x1);
                y = max(y,y1);
            }
        }
        ans.push_back({x,y});

        return ans;

    }
};

class Solution {
public:
    vector<bool> kidsWithCandies(vector<int>& candies, int extraCandies) {
        int maxi = *max_element(candies.begin(), candies.end()) - extraCandies;
        vector<bool> ans;
        for(auto num: candies){
            ans.push_back(num >= maxi);
        }
        return ans;
    }
};

class Solution {
public:
    int findMaxConsecutiveOnes(vector<int>& nums) {
        nums.push_back(0);
        int z = -1;
        int ans = 0;
        int n = nums.size();

        for(int i = 0; i < n; i++){
            if(nums[i] == 0){
                ans = max(ans, i - z - 1);
                z = i;
            }
        }

        return ans;
    }
};

class Solution {
public:
    int maxDistToClosest(vector<int>& seats) {

        vector<int> filled;
        int n = seats.size();

        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                filled.push_back(i);
            }
        }
        int m = filled.size();

        int ans = max(filled[0], n - 1 - filled[m - 1]);

        if (m > 1) {
            for (int j = 1; j < m; j++) {
                ans = max(ans, (filled[j] - filled[j - 1]) / 2);
            }
        }
        return ans;
    }
};

class Solution {
public:
    int maximumDifference(vector<int>& nums) {
        int n = nums.size(), ans = 0, maxi = nums[n-1];
        n-=2;
        while(n >= 0){
            ans = max(ans, maxi - nums[n]);
            maxi = max(maxi, nums[n]);
            n--;
        }
        return ans > 0 ? ans : -1;
    }
};

class Solution {
public:
    bool isMonotonic(vector<int>& nums) {
        int n = nums.size();
        if (n < 3) {
            return true;
        }
        bool inc = true, dec = true;
        int i = 1;
        while (i < n) {
            if (nums[i - 1] > nums[i]) {
                inc = false;
            }
            if (nums[i - 1] < nums[i]) {
                dec = false;
            }
            i++;
        }
        return inc || dec;
    }
};

class Solution {
public:
    bool checkPossibility(vector<int>& nums) {
        int n = nums.size();
        if (n < 3) {
            return true;
        }
        int exp = 0, real = 0, i = 0;
        while (i < n - 1) {
            if (nums[i] <= nums[i + 1]) {
                real++;
            }
            exp++;
            i++;
        }
        return exp - real < 2;
    }
};

class Solution {
public:
    vector<int> replaceElements(vector<int>& arr) {
        int maxi = -1;
        int n = arr.size();
        int i = n - 1;
        while (i >= 0) {
            int temp = arr[i];
            arr[i] = maxi;
            maxi = max(maxi, temp);
            i--;
        }
        return arr;
    }
};

class Solution {
public:
    vector<int> shuffle(vector<int>& nums, int n) {
        vector<int> ans(2 * n, 0);
        int i = 0;
        while (i < n) {
            ans[2 * i] = nums[i];
            ans[2 * i + 1] = nums[i + n];
            i++;
        }
        return ans;
    }
};

class Solution {
public:
    vector<string> summaryRanges(vector<int>& nums) {
        int n = nums.size();
        if (n == 0) {
            return {};
        }
        if (n == 1) {
            return {to_string(nums[0])};
        }

        vector<vector<int>> mat;
        mat.push_back({});
        mat[0].push_back(nums[0]);

        int i = 1;
        int r = 0;
        int c = 0;
        while (i < n) {
            if (nums[i] == mat[r][c] + 1) {
                mat[r].push_back(nums[i]);
                c++;
            } else {
                mat.push_back({});
                r++;
                mat[r].push_back(nums[i]);
                c = 0;
            }
            i++;
        }

        vector<string> ans;
        for (auto& it : mat) {
            int a = it[0];
            int b = it[it.size() - 1];

            if (a < b) {
                ans.push_back(to_string(a) + "->" + to_string(b));
            } else {
                ans.push_back(to_string(a));
            }
        }

        return ans;
    }
};

class Solution {
public:
    bool validMountainArray(vector<int>& arr) {
        int n = arr.size();
        if (n < 3) {
            return false;
        }
        int i = 0;
        while (i < n - 1 && arr[i] < arr[i + 1]) {
            i++;
        }
        int j = n - 1;
        while (j > 0 && arr[j] < arr[j - 1]) {
            j--;
        }
        return i == j && i > 0 && i < n - 1;
    }
};

class Solution {
public:
    int singleNonDuplicate(vector<int>& nums) {
        int x = 0;
        for (auto num : nums) {
            x ^= num;
        }
        return x;
    }
};

class Solution {
public:
    int countNegatives(vector<vector<int>>& grid) {
        int n = grid.size();
        int m = grid[0].size();
        int ans = 0;
        for(auto vec:grid){
            int i = 0;
            while(i < m){
                if(vec[i] < 0){
                    ans+=m-i;
                    break;
                }
                i++;
            }
        }
        return ans;
    }
};

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        int n = matrix.size();
        int m = matrix[0].size();

        int i1 = 0, i2 = 0, j1 = n-1, j2 = m-1;

        while(i1 <= j1 && i1 + i2 <= j1 + j2){
            int k1 = (i1 + j1)/2, k2 = (i2 + j2)/2;
            if(matrix[k1][k2] == target){
                return true;
            }
            if(matrix[k1][k2] < target){
                if(k2 == m-1){
                    i1 = k1 + 1;
                    i2 = 0;
                }else{
                    i1 = k1;
                    i2 = k2 + 1;
                }
            }else{
                if(k2 == 0){
                    j1 = k1 - 1;
                    j2 = 0;
                }else{
                    j1 = k1;
                    j2 = k2 - 1;
                }

            }
        }
        return false;
    }
};

class Solution {
public:
    int kthSmallest(vector<vector<int>>& matrix, int k) {
        priority_queue<int> pq;
        for(auto arr:matrix){
            for(auto num:arr){
                pq.push(num);
            }
        } 
        while(pq.size() > k){
            pq.pop();
        }
        return pq.top();
    }
};

class Solution {
public:
    int countSoldiers(vector<int>& row, int n) {
        if (row[n - 1] == 1) {
            return n;
        }
        if (row[0] == 0) {
            return 0;
        }
        int i = 0, j = n - 1, k;
        while (i <= j) {
            int k = i + (j - i) / 2;
            if (row[k] == 0 && row[k - 1] == 1) {
                return k;
            }
            if (row[k] == 1) {
                i = k + 1;
            } else {
                j = k - 1;
            }
        }
        return 0;
    }
    vector<int> kWeakestRows(vector<vector<int>>& mat, int k) {
        priority_queue<pair<int,int>> pq;
        int m = mat.size();
        int n = mat[0].size();
        for (int i = 0; i < m; i++) {
            pq.push({countSoldiers(mat[i], n), i});
            if(pq.size() > k){
                pq.pop();
            }
        }
        vector<int> ans;
        while(!pq.empty()){
            ans.push_back(pq.top().second);
            pq.pop();
        }
        reverse(ans.begin(),ans.end());
        return ans;
    }
};

class Solution {
public:
    int count_for_year(vector<vector<int>>& logs, int year){
        int ans = 0;
        for(auto log:logs){
            if(year < log[0]){
                break;
            }
            if(year >= log[0] && year < log[1]){
                ans++;
            }
        }
        return ans;
    }
    int maximumPopulation(vector<vector<int>>& logs) {
        sort(logs.begin(), logs.end(), [](vector<int>&A, vector<int>&B){
            return A[0] == B[0] ? A[1] < B[1] : A[0] < B[0];
        } );
        priority_queue<pair<int,int>> pq;

        for(int i = 1950; i <= 2050; i++){
            pq.push({count_for_year(logs,i),i});
        }

        int max_pop = pq.top().first, ans = pq.top().second;
        while(pq.top().first == max_pop){
            ans = pq.top().second;
            pq.pop();
        }
        return ans;
    }
};

class Solution {
public:
    // // TLE // Root cause: you mark a cell as visited when you pop it, not when you push it.
    // // Look at where image[i][j] = color runs (line 21). It only happens after a cell leaves the queue. Until then, the cell still holds target, so every neighbour that checks it before that point pushes it again.
    // vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
    //     int target = image[sr][sc];
    //     if(color == target){
    //         return image;
    //     }

    //     int m = image.size();
    //     int n = image[0].size();

    //     queue<pair<int,int>> q;
    //     q.push({sr,sc});

    //     while(!q.empty()){
    //         pair<int,int> p = q.front();
    //         q.pop();

    //         int i = p.first, j = p.second;

    //         image[i][j] = color;

    //         if(i + 1 < m && image[i+1][j] == target){
    //             q.push({i+1,j});
    //         }
    //         if(i - 1 >= 0 && image[i-1][j] == target){
    //             q.push({i-1,j});
    //         }
    //         if(j + 1 < n && image[i][j+1] == target){
    //             q.push({i,j+1});
    //         }
    //         if(j - 1 >= 0 && image[i][j-1] == target){
    //             q.push({i,j-1});
    //         }
    //     }

    //     return image;
    // }
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
        int target = image[sr][sc];
        if(color == target){
            return image;
        }

        int m = image.size();
        int n = image[0].size();

        queue<pair<int,int>> q;
        image[sr][sc] = color;
        q.push({sr,sc});

        while(!q.empty()){
            pair<int,int> p = q.front();
            q.pop();

            int i = p.first, j = p.second;


            if(i + 1 < m && image[i+1][j] == target){
                image[i+1][j] = color;
                q.push({i+1,j});
            }
            if(i - 1 >= 0 && image[i-1][j] == target){
                image[i-1][j] = color;
                q.push({i-1,j});
            }
            if(j + 1 < n && image[i][j+1] == target){
                image[i][j+1] = color;
                q.push({i,j+1});
            }
            if(j - 1 >= 0 && image[i][j-1] == target){
                image[i][j-1] = color;
                q.push({i,j-1});
            }
        }

        return image;
    }
};

