class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n = prices.size();
        if (n < 2) {
            return 0;
        }

        int maxi = prices[n - 1];
        int profit = 0;
        n -= 2;

        while (n >= 0) {
            profit = max(profit, maxi - prices[n]);
            maxi = max(maxi, prices[n]);
            n--;
        }

        return profit;
    }
};

class Solution {
public:
    int recur(vector<int>& cost, int i) {
        if (i < 2) {
            return 0;
        }
        return min(recur(cost, i - 1) + cost[i - 1],
                   recur(cost, i - 2) + cost[i - 2]);
    }
    int tab(vector<int>& cost) {
        int n = cost.size();
        vector<int> dp(n + 1, -1);
        dp[0] = 0;
        dp[1] = 0;
        for (int i = 2; i <= n; i++) {
            dp[i] = min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
        }
        return dp[n];
    }
    int minCostClimbingStairs(vector<int>& cost) {
        // return recur(cost, cost.size());
        return tab(cost);
    }
};

#define MAX 10001
class Solution {
public:
    int recur(vector<int>& coins, int amount) {
        if (amount == 0) {
            return 0;
        }
        if (amount < 0) {
            return MAX;
        }
        int ans = MAX;
        for (auto coin : coins) {
            ans = min(ans, 1 + recur(coins, amount - coin));
        }
        return ans;
    }
    int use_recur(vector<int>& coins, int amount) {
        int ans = recur(coins, amount);
        return ans == MAX ? -1 : ans;
    }
    int memo(vector<int>& coins, int amount, vector<int>& dp) {
        if (amount == 0) {
            return 0;
        }
        if (amount < 0) {
            return MAX;
        }
        if (dp[amount] < MAX) {
            return dp[amount];
        }
        int ans = MAX;
        for (auto coin : coins) {
            ans = min(ans, 1 + memo(coins, amount - coin, dp));
        }
        return dp[amount] = ans;
    }
    int use_memo(vector<int>& coins, int amount) {
        vector<int> dp(amount + 1, MAX);
        int ans = memo(coins, amount, dp);
        return ans == MAX ? -1 : ans;
    }
    int tab(vector<int>& coins, int amount) {
        vector<int> dp(amount + 1, MAX);
        dp[0] = 0;
        int i = 1;
        while (i <= amount) {
            for (auto coin : coins) {
                if (i >= coin) {
                    dp[i] = min(dp[i], 1 + dp[i - coin]);
                }
            }
            i++;
        }
        return dp[amount] == MAX ? -1 : dp[amount];
    }
    int coinChange(vector<int>& coins, int amount) {
        // return use_recur(coins, amount);
        // return use_memo(coins, amount);
        return tab(coins, amount);
    }
};

class Solution {
public:
    int fourSumCount(vector<int>& nums1, vector<int>& nums2, vector<int>& nums3,
                     vector<int>& nums4) {

        int n = nums1.size();
        unordered_map<int, int> mp1, mp2;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mp1[nums1[i] + nums2[j]]++;
                mp2[-nums3[i] - nums4[j]]++;
            }
        }

        int ans = 0;
        for (auto p : mp1) {
            int key = p.first;
            if (mp2.contains(key)) {
                ans += mp2[key] * (p.second);
            }
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> findDisappearedNumbers(vector<int>& nums) {
        int n = nums.size();
        for(int i = 0; i < n; i++){
            nums[abs(nums[i])-1] = -1*abs(nums[abs(nums[i])-1]);
        }
        vector<int> ans;
        for(int i = 0; i < n; i++){
            if(nums[i] > 0){
                ans.push_back(i + 1);
            }
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int,int> mp;
        int i = 0;
        for(auto it:nums){
            if(mp.contains(target - it)){
                return {mp[target-it],i};
            }
            mp[it] = i++;
        }
        return {};
    }
};

class Solution {
public:
    int numPairsDivisibleBy60(vector<int>& time) {
        int n = time.size();
        if (n < 2) {
            return 0;
        }
        int ans = 0;
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                ans += (time[i] + time[j]) % 60 == 0 ? 1 : 0;
            }
        }
        return ans;
    }
};

class OrderedStream {
    vector<string> stream;
    int index;
    int n;

public:
    OrderedStream(int n) {
        stream.resize(n, "");
        index = 0;
        this->n = n;
    }

    vector<string> insert(int idKey, string value) {
        stream[idKey - 1] = value;
        vector<string> ans;
        while(index < n && stream[index].size() > 0){
            ans.push_back(stream[index++]);
        }
        return ans;
    }
};

