class Solution {
public:
    // int majorityElement(vector<int>& nums) {
    //     unordered_map<int,int> mp;
    //     int n = nums.size();
    //     for(auto num:nums){
    //         mp[num]++;
    //         if(mp[num] > n/2){
    //             return num;
    //         }
    //     }
    //     return -1;
    // }


    // most optimla using Boyer-Moore Voting Algorithm // 
    // The core idea is: Whenever we encounter two different numbers, cancel them out.
    int majorityElement(vector<int>& nums) { 
        int ans = nums[0];
        int votes = 1;
        int n = nums.size();
        if(n == 1){
            return ans;
        }    
        for(int i = 1; i < n; i++){
            if(votes == 0){
                ans = nums[i];
                votes++;
            }
            else if(nums[i] == ans){
                votes++;
            }else{
                votes--;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int findJudge(int n, vector<vector<int>>& trust) {
        unordered_map<int, bool> belives;
        unordered_map<int, int> freq;
        for (auto arr : trust) {
            int a = arr[0];
            int b = arr[1];
            belives[a] = true;
            freq[b]++;
        }
        vector<int> ans;
        for (int i = 1; i < n + 1; i++) {
            if (!belives[i] && freq[i] >= n - 1) {
                ans.push_back(i);
            }
        }
        return ans.size() == 1 ? ans[0] : -1;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* modifiedList(vector<int>& nums, ListNode* head) {
        unordered_set<int> st;
        for (auto num : nums) {
            st.insert(num);
        }
        while (st.contains(head->val)) {
            head = head->next;
        }
        auto temp = head;
        while (temp != nullptr && temp->next != nullptr) {
            if (st.contains(temp->next->val)) {
                temp->next = temp->next->next;
            } else {
                temp = temp->next;
            }
        }
        return head;
    }
};

