class Solution {
public:
    int numIdenticalPairs(vector<int>& nums) {
        unordered_map<int, int> mp;
        for (auto it : nums) {
            mp[it]++;
        }
        int ans = 0;
        for (auto it : mp) {
            int n = it.second;
            ans += (n * (n - 1)) / 2;
        }
        return ans;
    }
};

class RandomizedSet {
    unordered_set<int> st;

public:
    RandomizedSet() {}

    bool insert(int val) {
        if (st.contains(val)) {
            return false;
        }
        st.insert(val);
        return true;
    }

    bool remove(int val) {
        if (st.contains(val)) {
            st.erase(val);
            return true;
        }
        return false;
    }

    int getRandom() {
        int i = rand() % (st.size());
        auto it = st.begin();
        advance(it, i);
        return *it;
    }
};

