class Solution {
public:
    void setZeroes(vector<vector<int>>& matrix) {
        unordered_map<int, bool> iz;
        unordered_map<int, bool> jz;

        int m = matrix.size();
        int n = matrix[0].size();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 0) {
                    iz[i] = true;
                    jz[j] = true;
                }
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (iz[i] || jz[j]) {
                    matrix[i][j] = 0;
                }
            }
        }
    }
};

class Solution {

public:
    bool hasDuplicates(vector<vector<char>>& board, int x1, int x2, int y1,
                       int y2) {
        unordered_map<char, int> freq;
        for (int y = y1; y <= y2; y++) {
            for (int x = x1; x <= x2; x++) {
                char ch = board[y][x];
                freq[ch]++;
                if (isdigit(ch) && freq[ch] > 1) {
                    return true;
                }
            }
        }
        return false;
    }
    bool isValidSudoku(vector<vector<char>>& board) {
        for (int i = 0; i < 9; i++) {
            bool rowCheck = hasDuplicates(board, 0, 8, i, i);
            bool colCheck = hasDuplicates(board, i, i, 0, 8);
            bool blockCkeck = hasDuplicates(board, 3 * (i % 3), 3 * (i % 3) + 2,
                                            3 * (i / 3), 3 * (i / 3) + 2);
            if (rowCheck || colCheck || blockCkeck) {
                return false;
            }
        }
        return true;
    }
};

class Solution {
public:
    int equalPairs(vector<vector<int>>& grid) {
        int n = grid.size();
        if(n < 2){
            return n;
        }
        unordered_map<string,int> rows;
        unordered_map<string,int> columns;
        for(int i = 0; i < n; i++){
            string row = "", column = "";
            for(int j = 0; j < n; j++){
                row += "-" + to_string(grid[i][j]);
                column += "-" + to_string(grid[j][i]);
            }
            rows[row]++;
            columns[column]++;
        }
        int ans = 0;
        for(auto p:rows){
            if(columns.contains(p.first)){
                ans+=(p.second)*(columns[p.first]);
            }
        }
        return ans;
    }
};

class Solution {
public:
    int coordinates_to_integer(vector<int>& coordinates) {
        return coordinates[0] * 3 + coordinates[1] + 1;
    }
    string tictactoe(vector<vector<int>>& moves) {
        int n = moves.size();
        if (n < 5) {
            return "Pending";
        }
        set<int> A_moves;
        set<int> B_moves;

        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                A_moves.insert(coordinates_to_integer(moves[i]));
            } else {
                B_moves.insert(coordinates_to_integer(moves[i]));
            }
        }

        vector<vector<int>> Winning_moves = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9},
                                             {1, 4, 7}, {2, 5, 8}, {3, 6, 9},
                                             {1, 5, 9}, {3, 5, 7}};

        for (auto combination : Winning_moves) {
            if (A_moves.contains(combination[0]) &&
                A_moves.contains(combination[1]) &&
                A_moves.contains(combination[2])) {
                return "A";
            }
            if (B_moves.contains(combination[0]) &&
                B_moves.contains(combination[1]) &&
                B_moves.contains(combination[2])) {
                return "B";
            }
        }

        return n == 9 ? "Draw" : "Pending";
    }
};

class Solution {
public:
    int subarraysDivByK(vector<int>& nums, int k) {
        int n = nums.size();
        if (n == 1) {
            return nums[0] % k == 0 ? 1 : 0;
        }
        int sum = 0;
        for (auto& num : nums) {
            sum += num;
            num = sum;
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                sum = i == 0 ? nums[j] : nums[j] - nums[i - 1];
                ans += sum % k == 0 ? 1 : 0;
            }
        }
        return ans;
    }
};

class Solution {
public:
    bool containsNearbyDuplicate(vector<int>& nums, int k) {
        unordered_map<int, int> mp;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            if (mp.contains(nums[i]) && i - mp[nums[i]] <= k) {
                return true;
            }
            mp[nums[i]] = i;
        }
        return false;
        ;
    }
};

class Solution {
public:
    int findLHS(vector<int>& nums) {
        map<int, int> mp;
        for (auto num : nums) {
            mp[num]++;
        }
        int lastVal = mp.begin()->first;
        int ans = 0;
        for (auto it : mp) {
            if (it.first - lastVal == 1) {
                ans = max(ans, it.second + mp[lastVal]);
            }
            lastVal = it.first;
        }
        return ans;
    }
};

