                return true;
            }
            mp[it]++;
        }
        return false;
    }
};

class Solution {
public:
    vector<int> findDuplicates(vector<int>& nums) {
        vector<int> ans;
        int n = nums.size();

        for (int i = 0; i < n; i++) {
            int j = abs(nums[i]) - 1;
            if (nums[j] < 0) {
                ans.push_back(j + 1);
            } else {
                nums[j] *= -1;
            }
        }

        return ans;
    }
};

class Solution {
public:
    vector<int> arrayRankTransform(vector<int>& arr) {
        map<int, int> mp;
        int i = 0;
        for (auto it : arr) {
            mp[it] = 0;
        }
        i = 1;
        for (auto& it : mp) {
            it.second = i++;
        }
        for (auto& it : arr) {
            it = mp[it];
        }
        return arr;
    }
};

