class Solution {
public:
    int digit_sum(int num) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        return sum;
    }
    int maximumSum(vector<int>& nums) {
        int ans = -1;
        unordered_map<int, int> mp;
        for (auto num : nums) {
            int sum = digit_sum(num);
            if (mp.contains(sum)) {
                ans = max(ans, num + mp[sum]);
                mp[sum] = max(mp[sum], num);
            } else {
                mp[sum] = num;
            }
        }
        return ans;
    }
};

class Solution {
public:
    vector<string> split_files(string& str) {
        vector<string> split_by_spaces;
        int n = str.size();
        vector<int> spaces(1, -1);
        for (int i = 0; i < n; i++) {
            if (str[i] == ' ') {
                spaces.push_back(i);
            }
        }
        spaces.push_back(n);
        int m = spaces.size();
        for (int i = 1; i < m; i++) {
            int j = spaces[i - 1] + 1;
            int l = spaces[i] - j;
            split_by_spaces.push_back(str.substr(j, l));
        }
        int p = split_by_spaces.size();
        vector<string> files;
        for (int i = 1; i < p; i++) {
            files.push_back(split_by_spaces[0] + "/" + split_by_spaces[i]);
        }
        return files;
    }
    void map_file_by_content(unordered_map<string, vector<string>>& mp,
                             vector<string>& files) {
        for (auto str : files) {
            int n = str.size();
            int index = str.find('(');
            string file = str.substr(0, index);
            string content = str.substr(index, n - index);
            if (!mp.contains(content)) {
                mp[content] = {};
            }
            mp[content].push_back(file);
        }
    }
    vector<vector<string>> findDuplicate(vector<string>& paths) {
        unordered_map<string, vector<string>> mp;
        for (auto path : paths) {
            vector<string> files = split_files(path);
            map_file_by_content(mp, files);
        }
        vector<vector<string>> ans;
        for (auto p : mp) {
            if (p.second.size() > 1) {
                ans.push_back(p.second);
            }
        }
        return ans;
    }
};

class Solution {
public:
    int numUniqueEmails(vector<string>& emails) {
        unordered_set<string> st;
        for (auto email : emails) {

            bool plus = false;
            bool atrate = false;

            string str = "";
            for (auto ch : email) {
                if (ch == '+') {
                    plus = true;
                }
                if (ch == '@') {
                    atrate = true;
                }
                if ((!plus && !atrate && ch != '.') || atrate) {
                    str.push_back(ch);
                }
            }

            st.insert(str);
        }
        return st.size();
    }
};

class Solution {
public:
    bool isAlienSorted(vector<string>& words, string order) {
        unordered_map<char, char> alien_to_human;
        vector<string> human_words;
        int i = 0, n = words.size();
        for (auto ch : order) {
            alien_to_human[ch] = 'a' + i++;
        }
        for (auto& word : words) {
            int j = 0, m = word.size();
            while (j < m) {
                word[j] = alien_to_human[word[j]];
                j++;
            }
            human_words.push_back(word);
        }
        sort(human_words.begin(), human_words.end());
        i = 0;

        while (i < n) {
            if (words[i] != human_words[i]) {
                return false;
            }
            i++;
        }

        return true;
    }
};

class Solution {
public:
    string mostCommonWord(string paragraph, vector<string>& banned) {
        unordered_map<string, int> mp;
        string str = "";
        for (auto ch : paragraph) {
            if (isalpha(ch)) {
                str.push_back(tolower(ch));
            } else {
                if (str.size() > 0) {
                    mp[str]++;
                    str = "";
                }
            }
        }
        if (str.size() > 0) {
            mp[str]++;
            str = "";
        }

        for (auto word : banned) {
            for (auto& ch : word) {
                tolower(ch);
            }
            mp[word] = -1;
        }
        string ans = "";
        mp[""] = -1;

        for (auto it : mp) {
            if (it.second > mp[ans]) {
                ans = it.first;
            }
        }

        return ans;
    }
};

