class Solution {
public:
    struct Obj {
        char ch;
        long long int score;
        Obj(char ch, long long int score) {
            this->ch = ch;
            this->score = score;
        }
    };
    long long int rankScore(vector<int>& scores) {
        long long int ans = 0;
        for (int i = 0; i < 26; i++) {
            ans += scores[i] * pow(2, 26 - i - 1);
        }
        return ans;
    }
    string rankTeams(vector<string>& votes) {
        vector<vector<int>> rank(26, vector<int>(26, 0));
        int t = votes[0].size();
        for (auto vote : votes) {
            for (int i = 0; i < t; i++) {
                rank[vote[i] - 'A'][i]++;
            }
        }
        vector<Obj> matrix;
        for (int i = 0; i < 26; i++) {
            char ch = 'A' + i;
            long long int score = rankScore(rank[i]);
            if (score > 0) {
                Obj newObj(ch, score);
                matrix.push_back(newObj);
            }
        }
        sort(matrix.begin(), matrix.end(), [](Obj& A, Obj& B) {
            return A.score == B.score ? A.ch < B.ch : A.score > B.score;
        });
        string ans;
        for (auto it : matrix) {
            ans.push_back(it.ch);
        }
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> kSmallestPairs(vector<int>& nums1, vector<int>& nums2,
                                       int k) {
        int n = nums1.size();
        n = min(k, n);
        int m = nums2.size();
        m = min(k, m);

        priority_queue<pair<int, pair<int, int>>> pq;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                pq.push({nums1[i] + nums2[j], {nums1[i], nums2[j]}});
                if(pq.size() > k){
                    pq.pop();
                }
            }
        }

        vector<vector<int>> ans;

        while (pq.size() > 0) {
            ans.push_back({pq.top().second.first, pq.top().second.second});
            pq.pop();
        }

        return ans;
    }
};

class Solution {
public:
    int lastStoneWeight(vector<int>& stones) {
        priority_queue<int> pq;
        for (auto num : stones) {
            pq.push(num);
        }
        while (pq.size() > 1) {
            int w1 = pq.top();
            pq.pop();
            int w2 = pq.top();
            pq.pop();
            if (w1 > w2) {
                pq.push(w1 - w2);
            }
        }
        if (pq.empty()) {
            return 0;
        }
        return pq.top();
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<vector<int>> spiralMatrix(int m, int n, ListNode* head) {
        vector<int> values;
        while(head!=nullptr){
            values.push_back(head->val);
            head = head->next;
        }

        int x, y, x1 = 0, y1 = 0, x2 = n - 1, y2 = m - 1, v = values.size(), k = 0;

        vector<vector<int>> ans(m, vector<int>(n, -1));

        while(k < v){
            x = x1, y = y1;
            while(x <= x2 && k < v){
                ans[y][x++] = values[k++];
            }
            y1++;
            x = x2, y = y1;
            while(y <= y2 && k < v){
                ans[y++][x] = values[k++];
            }
            x2--;
            x = x2, y = y2;
            while(x >= x1 && k < v){
                ans[y][x--] = values[k++];
            }
            y2--;
            x = x1, y = y2;
            while(y >= y1 && k < v){
                ans[y--][x] = values[k++];
            }
            x1++;
        }

        return ans;
    }
};

class BrowserHistory {
    int current;
    vector<string> history;

public:
    BrowserHistory(string homepage) {
        current = 0;
        history.push_back(homepage);
    }

    // void visit(string url) {
    //     vector<string> new_history(history.begin(),
    //                                history.begin() + current + 1);
    //     new_history.push_back(url);
    //     current++;
    //     history = new_history;
    // }

    void visit(string url) {
        history.erase(history.begin() + current + 1, history.end());
        history.push_back(url);
        current++;
    }

    string back(int steps) {
        current = max(0, current - steps);
        return history[current];
    }

    string forward(int steps) {
        int n = history.size();
        current = min(n - 1, current + steps);
        return history[current];
    }
};

