class Solution {
public:
    vector<int> addToArrayForm(vector<int>& num, int k) {
        int n = num.size();
        reverse(num.begin(), num.end());
        for (auto& digit : num) {
            if (k == 0) {
                break;
            }
            k += digit;
            digit = k % 10;
            k /= 10;
        }
        while (k > 0) {
            num.push_back(k % 10);
            k /= 10;
        }
        reverse(num.begin(), num.end());
        return num;
    }
};

class Solution {
