                ans++;
            } else if (num > 999 && num < 10000) {
                ans++;
            } else if (num > 99999 && num < 1000000) {
                ans++;
            }
        }
        return ans;
    }
};

class Solution {
public:
    void resort(vector<int>& nums, int n) {
        int i = 0, last = nums[n - 1];
        while (i < n - 1 && nums[i] <= last) {
            i++;
        }
        int j = n - 1;
        while (j > i) {
            nums[j] = nums[j - 1];
            j--;
        }
        nums[j] = last;
    }
    void add1s(vector<int>& nums, int n) {
        for (auto& num : nums) {
            num++;
        }
        nums[n - 1]--;
    }
    int minMoves(vector<int>& nums) {
        int n = nums.size();
        sort(nums.begin(), nums.end());

        int ans = 0;
        while (nums[0] != nums[n - 1]) {
            add1s(nums, n);
            ans++;
            resort(nums, n);
        }

        return ans;
    }
};

class Solution {
public:
    long long zeroFilledSubarray(vector<int>& nums) {
        vector<int> idx(1, 0);
        int i = 1;
        for (auto it : nums) {
            if (it != 0) {
                idx.push_back(i);
            }
            i++;
        }
        idx.push_back(nums.size() + 1);

        int n = idx.size();
        i = 1;

        long long ans = 0;
        while (i < n) {
            long long a = idx[i] - idx[i - 1];
            ans += ((a - 1) * a) / 2;
            i++;
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> plusOne(vector<int>& digits) {
        int carry = 1, n = digits.size();

        reverse(digits.begin(), digits.end());

        for(auto &num: digits){
            carry+= num;
            num = carry%10;
            carry/=10;
        }

        while(carry > 0){
            digits.push_back(carry%10);
            carry/=10;
        }

        reverse(digits.begin(), digits.end());

        return digits;

    }
};

class Solution {
public:
    vector<int> threeEqualParts(vector<int>& arr) {
        int ones = 0;
        for (auto num : arr) {
            ones += num;
        }
        if (ones % 3 != 0) {
            return {-1, -1};
        }
        if (ones == 0) {
            return {0, 2};
        }

        int i = 0, j = 0, k = 0, n = arr.size(), temp = 0;

        while (k < n) {
            if (arr[k] == 1) {
                temp++;
            }
            if (temp <= ones / 3) {
                i++;
            }
            if (temp <= 1 + (2 * ones) / 3) {
                j++;
            }
            k++;
        }

        int l = min(i + 1, min(j - 1 - i, n - j));

        int x = i, y = j - 1, z = n - 1;

        while (l > 0) {
            if (arr[x] != arr[y] || arr[z] != arr[y] || arr[x] != arr[z]) {
                return {-1, -1};
            }
            x--;
            y--;
            z--;
            l--;
        }

        return {i, j};
    }
};

class ProductOfNumbers {
    vector<int> prod;
    int n;

public:
    ProductOfNumbers() { n = 0; }

    void add(int num) {
        n++;
        prod.push_back(num);
    }

    int getProduct(int k) {
        k = n - k;
        int ans = 1;
        while (k < n) {
            ans *= prod[k++];
        }
        return ans;
    }
};

