class Solution {
    vector<int> nums;
    vector<int> nums_const;
public:
    Solution(vector<int>& nums) {
        this->nums_const= nums;
        this->nums= nums;
    }

    vector<int> reset() {
        nums = nums_const;
        return nums;
    }

    vector<int> shuffle() {
        int n = nums.size();
        while(n > 0){
            int i = rand()%n;
            int temp = nums[i];
            nums[i] = nums[n-1];
            nums[n-1] = temp;
            n--;
        }
        return nums;
    }
};

