class Solution {
public:
    int countPrimes(int n) {
        if (n < 3) {
            return 0;
        }
        vector<bool> arr(n, true);
        arr[0] = false;
        arr[1] = false;
        for (int i = 2; i*i < n; i++) {
            if (arr[i]) {
                int j = 2;
                while (j * i < n) {
                    arr[j * i] = false;
                    j++;
                }
            }
        }
        int ans = 0;
        for(auto isPrime:arr){
            ans += isPrime ? 1 : 0;
        }
        return ans;
    }
};

class Solution {
public:
    bool checkStraightLine(vector<vector<int>>& coordinates) {
        int n = coordinates.size();
        if (n < 3) {
            return true;
        }

        for (int i = 2; i < n; i++) {
            int x1 = coordinates[i - 2][0];
            int x2 = coordinates[i - 1][0];
            int x3 = coordinates[i][0];
            int y1 = coordinates[i - 2][1];
            int y2 = coordinates[i - 1][1];
            int y3 = coordinates[i][1];

            if ((x1 - x2) * (y2 - y3) != (x2 - x3) * (y1 - y2)) {
                return false;
            }
        }
        return true;
    }
};

class Solution {
public:
    void transpose(vector<vector<int>>& matrix) {
        int n = matrix.size();
        vector<vector<int>> trans(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                trans[i][j] = matrix[j][i];
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = trans[i][j];
            }
        }
    }
    void hflip(vector<vector<int>>& matrix) {
        int n = matrix.size();
        for (auto& arr : matrix) {
            for (int i = 0; i < n / 2; i++) {
                int temp = arr[i];
                arr[i] = arr[n - 1 - i];
                arr[n - 1 - i] = temp;
            }
        }
    }

    void rotate(vector<vector<int>>& matrix) {
        transpose(matrix);
        hflip(matrix);
    }
};

class Solution {
public:
    int sumFourDivisors(vector<int>& nums) {
        unordered_map<int, int> freq;
        unordered_map<int, int> sums;
        for (auto it : nums) {
            freq[it]++;
            if (!sums.contains(it)) {
                int i = 2;
                int j = floor(abs(sqrt(it)));

                unordered_set<int> divisors;
                while (i <= j) {
                    if (it % i == 0) {
                        divisors.insert(i);
                        divisors.insert(it / i);
                    }
                    i++;
                }
                sums[it] = 0;
                if (divisors.size() == 2) {
                    sums[it] = 1 + it;
                    for (auto dt : divisors) {
                        sums[it] += dt;
                    }
                }
            }
        }
        int ans = 0;
        for (auto it : sums) {
            int sum = it.second;
            if (sum > 0) {
                ans += freq[it.first] * sum;
            }
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> missingRolls(vector<int>& rolls, int mean, int n) {
        int m = rolls.size();
        int sum = mean * (m + n);
        for (auto val : rolls) {
            sum -= val;
        }
        if (sum < n || sum > 6*n) {
            return {};
        }
        int whole = sum/n;
        int left = sum - whole*n;
        vector<int> ans(n, whole);
        while(left > 0){
            ans[--left]++;
        }
        return ans;
    }
};

