class Solution {
public:
    string triangleType(vector<int>& nums) {
        int a = nums[0];
        int b = nums[1];
        int c = nums[2];

        if (a + b > c && b + c > a && a + c > b) {
            if (a == b || b == c || c == a) {
                if (a == b && b == c) {
                    return "equilateral";
                }
                return "isosceles";
            }
            return "scalene";
        }
        return "none";
    }
};

