class Solution {
public:
    vector<vector<int>> construct2DArray(vector<int>& original, int m, int n) {
        int k = original.size();
        vector<vector<int>> mat;

        if (k != m * n) {
            return mat;
        }

        vector<int> arr;
        for (int i = 0; i < k; i++) {
            arr.push_back(original[i]);
            if ((i + 1) % n == 0) {
                mat.push_back(arr);
                arr.clear();
            }
        }

        if (arr.size() > 0 && mat.size() < m) {
            mat.push_back(arr);
        }

        return mat;
    }
};

