class Solution {
public:
    long long maximumTripletValue(vector<int>& nums) {
        int n = nums.size(), largest, i;

        vector<int> leftLargest(n, 0);
        vector<int> rightLargest(n, 0);

        largest = 0;
        i = 1;
        while (i < n) {
            largest = max(largest, nums[i - 1]);
            leftLargest[i] = largest;
            i++;
        }

        largest = 0;
        i = n - 2;

        while (i >= 0) {
            largest = max(largest, nums[i + 1]);
            rightLargest[i] = largest;
            i--;
        }

        long long ans = 0;
        i = 1;
        while (i < n - 1) {
            long long I = leftLargest[i];
            long long J = nums[i];
            long long K = rightLargest[i];
            ans = max(ans, K * (I - J));
            i++;
        }

        return ans;
    }
};

class Solution {
public:
    int minimumAverageDifference(vector<int>& nums) {
        int n = nums.size();
        vector<long long> pref_sum(n, 0);
        long long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += nums[i];
            pref_sum[i] = sum;
        }
        long long average = sum;
        int index = 0;
        for (int i = 0; i < n; i++) {
            long long left = (pref_sum[i]) / (i + 1);
            long long right = 0;
            if (n - i - 1 > 0) {
                right = (sum - pref_sum[i]) / (n - i - 1);
            }
            if (average > abs(right - left)) {
                average = abs(right - left);
                index = i;
            }
        }
        return index;
    }
};

class Solution {
public:
    int waysToSplitArray(vector<int>& nums) {
        int n = nums.size();
        if (n < 2) {
            return 0;
        }
        long long sumr = 0, suml = 0;
        for (auto it : nums) {
            sumr += it;
        }
        int i = 0, ans = 0;

        while (i < n - 1) {
            suml += nums[i];
            sumr -= nums[i];
            if (suml >= sumr) {
                ans++;
            }
            i++;
        }

        return ans;
    }
};

class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        int n = nums.size();
        vector<int> left(n, 1), right(n, 1), ans(n, 1);

        for (int i = 1; i < n; i++) {
            left[i] = left[i - 1] * nums[i - 1];
            right[n - i - 1] = right[n - i] * nums[n - i];
        }

        for (int i = 0; i < n; i++) {
            ans[i] = left[i] * right[i];
        }

        return ans;
    }
};

