class Solution {
public:
    int firstStableIndex(vector<int>& nums, int k) {
        int n = nums.size();
        if (n == 1) {
            return 0;
        }
        vector<int> pre_max(n, -1);
        vector<int> suff_min(n, -1);
        int maxi = 0, mini = 1000000001;
        for (int i = 0; i < n; i++) {
            int j = n - 1 - i;
            maxi = max(nums[i], maxi);
            pre_max[i] = maxi;
            mini = min(nums[j], mini);
            suff_min[j] = mini;
        }
        for (int i = 0; i < n; i++) {
            if (pre_max[i] - suff_min[i] <= k) {
                return i;
            }
        }
        return -1;
    }
};

class Solution {
public:
    int longestSubarray(vector<int>& nums, int limit) {
        priority_queue<int, vector<int>, greater<int>> min_heap;
        priority_queue<int> max_heap;
        int ans = 1;
        for (auto it : nums) {
            min_heap.push(it);
            max_heap.push(it);
            if (max_heap.top() - min_heap.top() <= limit) {
                int m = max_heap.size();
                ans = max(ans, m);
            } else {
                min_heap = priority_queue<int, vector<int>, greater<int>>();
                max_heap = priority_queue<int>();
                min_heap.push(it);
                max_heap.push(it);
            }
        }
        if (max_heap.top() - min_heap.top() <= limit) {
            int m = max_heap.size();
            ans = max(ans, m);
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> merge(vector<int>&v1,vector<int>&v2){
        vector<int> v;
        int i = 0, j = 0, n = v1.size(), m = v2.size();
        while(i < n || j < m){
            if(i < n){
                v.push_back(v1[i++]);
            }
            if(j < m){
                v.push_back(v2[j++]);
            }
        }
        return v;
    }
    vector<int> deckRevealedIncreasing(vector<int>& deck) {
        int n = deck.size();
        if (n == 1) {
            return deck;
        }
        sort(deck.begin(), deck.end());
        vector<vector<int>> mat;
        int i = 0;
        int j = 0;
        while (n >= 1) {
            int m = (n + 1) / 2;
            vector<int> sub(deck.begin() + i, deck.begin() + i + m);
            if (j % 2 == 1) {
                reverse(sub.begin(), sub.end());
            }
            mat.push_back(sub);
            n -= m;
            i += m;
            j++;
        }
        int k = mat.size();
        if(k == 1){
            return mat[0];
        }
        vector<int> temp = mat[k-1];
        k-=2;
        while(k >= 0){
            temp = merge(mat[k--],temp);
        }
        return temp;
    }
};

class Solution {
public:
    double averageWaitingTime(vector<vector<int>>& customers) {
        int n = customers.size();
        int last_delivery_time = 0;
        double average = 0;
        for(int i = 0; i < n; i++){
            int arrival = customers[i][0];
            int time = customers[i][1];
            int waiting = max(last_delivery_time, arrival) + time -  arrival;
            average = (average*i + waiting)/(i+1);
            last_delivery_time = arrival + waiting;
        }
        return average;
    }
};

