class Solution {
public:
    vector<int> sumEvenAfterQueries(vector<int>& nums,
                                    vector<vector<int>>& queries) {
        int sum = 0;
        for (auto val : nums) {
            if (val % 2 == 0) {
                sum += val;
            }
        }
        vector<int> ans;
        for (auto q : queries) {
            int val = q[0], i = q[1];
            int old_val = nums[i];
            int new_val = old_val + val;
            nums[i] = new_val;

            if (old_val % 2 == 0) {
                sum -= old_val;
            }
            if (new_val % 2 == 0) {
                sum += new_val;
            }
            ans.push_back(sum);
        }
        return ans;
    }
};

class Solution {
public:
    int countDays(int days, vector<vector<int>>& meetings) {
        sort(meetings.begin(), meetings.end(),
             [](vector<int>& A, vector<int>& B) {
                 return A[0] == B[0] ? A[1] < B[1] : A[0] < B[0];
             });

        int x = meetings[0][0];
        int y = meetings[0][1];
        for (auto it : meetings) {
            if (y >= it[0]) {
                y = max(y, it[1]);
            } else {
                days -= y - x + 1;
                x = it[0];
                y = it[1];
            }
        }
        days -= y - x + 1;
        return days;
    }
};

