        int i = n / 20, j = n - 1 - n / 20, k = (9 * n) / 10;
        double ans = 0;
        while (i <= j) {
            double tmp = arr[i++];
            ans += tmp / k;
        }
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> minimumAbsDifference(vector<int>& arr) {
        sort(arr.begin(), arr.end());
        int n = arr.size();
        int mad = arr[n - 1] - arr[0];
        int i = 1;
        while (i < n) {
            mad = min(mad, arr[i] - arr[i - 1]);
            i++;
        }
        vector<vector<int>> ans;
        i = 1;
        while (i < n) {
            if (arr[i] - arr[i - 1] == mad) {
                ans.push_back({arr[i - 1], arr[i]});
            }
            i++;
        }
        return ans;
    }
};

class Solution {
public:
    int removeCoveredIntervals(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end(),
             [](vector<int>& A, vector<int>& B) {
                 return A[0] == B[0] ? A[1] < B[1] : A[0] < B[0];
             });
        vector<vector<int>> merged_intervals;
        int x = intervals[0][0];
        int y = intervals[0][1];

        for (auto it : intervals) {
            if (x == it[0]) {
                y = it[1];
            } else if (y < it[1]) {
                merged_intervals.push_back({x, y});
                x = it[0];
                y = it[1];
            }
        }
        return merged_intervals.size() + 1;
    }
};

class Solution {
public:
    int thirdMax(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int i = n-1;
        int count = 2;
        while(i > 0){
            if(nums[i-1] == nums[i]){
                i--;
            } else if(nums[i-1] <= nums[i]){
                i--;
                count--;
            }
            if(count == 0){
                return nums[i];
            }
        }
        return nums[n-1];
    }
};

