class Solution {
public:
    vector<string> findRelativeRanks(vector<int>& score) {
        int n = score.size();
        priority_queue<pair<int, int>> pq;
        for (int i = 0; i < n; i++) {
            pq.push({score[i], i});
        }
        int rank = 1;
        vector<string> ans(n, "");
        while (!pq.empty()) {
            auto p = pq.top();
            pq.pop();
            string val = rank == 1   ? "Gold Medal"
                         : rank == 2 ? "Silver Medal"
                         : rank == 3 ? "Bronze Medal"
                                     : to_string(rank);
            ans[p.second] = val;
            rank++;
        }
        return ans;
    }
};

