             });
        vector<vector<int>> ans;
        int x = intervals[0][0];
        int y = intervals[0][1];
        for (auto it : intervals) {
            if (y < it[0]) {
                ans.push_back({x, y});
                x = it[0];
            }
            y = max(y, it[1]);
        }
