        return ans;
    }
};

class Solution {
public:
    bool arrayStringsAreEqual(vector<string>& word1, vector<string>& word2) {
        string word = "";
        for (auto w : word1) {
            word += w;
        }
        int i = 0;
        for (auto w : word2) {
            for (auto ch : w) {
                if (ch != word[i]) {
                    return false;
                }
                i++;
            }
        }
