class Solution {
public:
    bool is_vowel_edged_word(string word) {
        int n = word.size();
        if (n == 0) {
            return false;
        }
        char front = word[0], back = word[n - 1];
        if ((front == 'a' || front == 'e' || front == 'i' || front == 'o' ||
             front == 'u') &&
            (back == 'a' || back == 'e' || back == 'i' || back == 'o' ||
             back == 'u')) {
            return true;
        }
        return false;
    }
    vector<int> vowelStrings(vector<string>& words,
                             vector<vector<int>>& queries) {
        int n = words.size(), sum = 0;
        vector<int> pref_sum(n, 0);
        for (int i = 0; i < n; i++) {
            sum += is_vowel_edged_word(words[i]) ? 1 : 0;
            pref_sum[i] = sum;
        }
        vector<int> ans;
        for (auto range : queries) {
            int A = range[0] > 0 ? pref_sum[range[0] - 1] : 0;
            int B = pref_sum[range[1]];
            ans.push_back(B - A);
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> minOperations(string boxes) {
        int n = boxes.size();

        if (n < 2) {
            return {0};
        }

        int N = 0, P = 0, NS = 0, PS = 0;

        for (int i = 1; i < n; i++) {
            if (boxes[i] == '1') {
                P++;
                PS += i;
            }
        }

        vector<int> ans(n, 0);

        if(boxes[0] == '0' && PS == 0){
            return ans;
        }

        for(int i = 0; i < n; i++){

            ans[i] = abs(NS) + abs(PS);

            if(boxes[i] == '1'){
                N++;
            }
            NS+=N;
            PS-=P;
            if(i < n-1 && boxes[i+1] == '1'){
                P--;
            }
        }

        return ans;
    }
};

class Solution {
public:
    string shiftingLetters(string s, vector<int>& shifts) {
        int n = shifts.size();
        if(n > 1){
            int j = n-2;
            while(j >= 0){
                shifts[j]+=shifts[j+1];
                shifts[j]%=26;
                j--;
            }
        }
        int i = 0;
        for(auto &ch:s){
            shifts[i]+=ch-'a';
            shifts[i]%=26;
            ch = 'a'+shifts[i];
            i++;
        }
        return s;
    }
};

#define ALPHA 26000000

class Solution {
public:
    char shiftChar(char ch, int num) {
        return 'a' + (ALPHA + num + ch - 'a') % 26;
    }
    string shiftingLetters(string s, vector<vector<int>>& shifts) {
        int n = s.size();
        int i = 0;

        unordered_map<int, int> mp;

        while (i < n) {
            mp[i++] = 0;
        }

        for (auto it : shifts) {
            i = it[0];
            while (i <= it[1]) {
                mp[i++] += it[2] * 2 - 1;
            }
        }

        i = 0;
        for (auto& ch : s) {
            ch = shiftChar(ch, mp[i++]);
        }

        return s;
    }
};

class Solution {
public:
    string generateGap(int n) {
        string gap(n, ' ');
        return gap;
    }
    string createLine(vector<string>& lineWords, int totalGap) {
        int n = lineWords.size();
        if (lineWords.size() == 1) {
            return lineWords[0] + generateGap(totalGap);
        }
        string gaps = generateGap(totalGap / (n - 1));
        string firstGap = gaps + generateGap(totalGap % (n - 1));

        string line = "";

        for (int i = 0; i < n; i++) {
            if (i == 0) {
                line += lineWords[i] + firstGap;
            } else if (i == n - 1) {
                line += lineWords[i];
            } else {
                line += lineWords[i] + gaps;
            }
        }

        return line;
    }
    vector<string> fullJustify(vector<string>& words, int maxWidth) {
        int l = 0;
        int wordsLength = 0;
        vector<string> temp;
        vector<string> ans;

        for (auto str : words) {
            if (l == 0) {
                temp = {str};
                l = str.size();
                wordsLength = str.size();
            } else if (l + str.size() + 1 > maxWidth) {
                ans.push_back(createLine(temp, maxWidth - wordsLength));
                temp = {str};
                l = str.size();
                wordsLength = str.size();
            } else {
                temp.push_back(str);
                l += str.size() + 1;
                wordsLength += str.size();
            }
        }
        if (l > 0) {
            ans.push_back(createLine(temp, maxWidth - wordsLength));
        }
        return ans;
    }
};

class Solution {
public:
    vector<string> reorderLogFiles(vector<string>& logs) {
        vector<string> words;
        vector<string> digits;
        for (auto it : logs) {
            int i = it.find(' ');
            if (isalpha(it[i + 1])) {
                words.push_back(it);
            } else {
                digits.push_back(it);
            }
        }
        sort(words.begin(), words.end(), [](string& word1, string& word2) {
            int i = word1.find(' ');
            string p1 = word1.substr(0, i);
            string c1 = word1.substr(i + 1, word1.size() - i - 1);
            int j = word2.find(' ');
            string p2 = word2.substr(0, j);
            string c2 = word2.substr(j + 1, word2.size() - j - 1);
            return c1 == c2 ? p1 < p2 : c1 < c2;
        });
        int i = 0;
        for (auto it : words) {
            logs[i++] = it;
        }
        for (auto it : digits) {
            logs[i++] = it;
        }
        return logs;
    }
};

class Solution {
public:
    string getCommonPrefix(string& A, string& B) {
        int n = min(A.size(), B.size());
        string ans = "";
        for (int i = 0; i < n; i++) {
            if (A[i] != B[i]) {
                break;
            }
            ans += A[i];
        }
        return ans;
    }
    string longestCommonPrefix(vector<string>& strs) {
        string ans = strs[0];
        for (auto word : strs) {
            ans = getCommonPrefix(ans, word);
        }
        return ans;
    }
};

class Solution {
public:
    int removeElement(vector<int>& nums, int val) {
        int i = 0, j = nums.size() - 1, k = 0;
        while (i < j) {
            if (nums[i] == val && nums[j] != val) {
                int temp = nums[i];
                nums[i] = nums[j];
                nums[j] = temp;
            }
            while (nums[i] != val) {
                i++;
            }
            while (nums[j] == val) {
                j--;
            }
        }
        while (nums[k] != val) {
            k++;
        }
        return k;
    }
};

