    int smallestDistancePair(vector<int>& nums, int k) {
        priority_queue<int> pq;
        int n = nums.size();
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                int diff = abs(nums[i] - nums[j]);
                pq.push(diff);
                if (pq.size() > k) {
                    pq.pop();
                }
            }
        }
        return pq.top();
    }
