class Solution {
public:
    bool canVisitAllRooms(vector<vector<int>>& rooms) {
        int n = rooms.size();
        vector<bool> visited(n, false);
        queue<int> q;

        int not_visited = n;
        q.push(0);
        visited[0] = true;
        not_visited--;

        while (!q.empty()) {
            int node = q.front();
            q.pop();
            for (auto room : rooms[node]) {
                if (!visited[room]) {
                    q.push(room);
                    visited[room] = true;
                    not_visited--;
                }
            }
        }

        return not_visited == 0;
    }
};

class Solution {
public:
    bool validPath(int n, vector<vector<int>>& edges, int source, int destination) {
        if(n==1){
            return true;
        }
        vector<vector<int>> adj(n);
        for(auto edge:edges){
            int u = edge[0];
            int v = edge[1];
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        queue<int> q;
        unordered_map<int,bool> visited;

        q.push(source);
        visited[source] = true;

        while(!q.empty()){
            int top = q.front();
            q.pop();
            for(auto node:adj[top]){
                if(node==destination){
                    return true;
                }
                if(visited[node]==false){
                    q.push(node);
                    visited[node]=true;
                }
            }
        }
        return false;
    }
};

class Solution {
public:
    int findCircleNum(vector<vector<int>>& isConnected) {

        int n = isConnected.size();

        unordered_map<int, bool> visited;
        for (int i = 0; i < n; i++) {
            visited[i] = false;
        }

        vector<vector<int>> adj(n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (isConnected[i][j]) {
                    adj[i].push_back(j);
                    adj[j].push_back(i);
                }
            }
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i] == false) {
                queue<int> q;
                q.push(i);
                visited[i] = true;
                while (!q.empty()) {
                    int node = q.front();
                    q.pop();
                    for (auto leaf : adj[node]) {
                        if (visited[leaf] == false) {
                            visited[leaf] = true;
                            q.push(leaf);
                        }
                    }
                }
                ans++;
            }
        }

        return ans;
    }
};

