class StockPrice {
    map<int, int> records;
    map<int, int> freq;

public:
    StockPrice() {}

    void update(int timestamp, int price) {
        if (records.contains(timestamp)) {
            freq[records[timestamp]]--;
            if (freq[records[timestamp]] == 0) {
                freq.erase(records[timestamp]);
            }
        }
        records[timestamp] = price;
        freq[price]++;
    }

    int current() {
        auto it = records.end();
        it--;
        return (*it).second;
    }

    int maximum() {
        auto it = freq.end();
        it--;
        return (*it).first;
    }

    int minimum() {
        auto it = freq.begin();
        return (*it).first;
    }
};

