/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    ListNode* getIntersectionNode(ListNode* headA, ListNode* headB) {
        auto a = headA, b = headB;
        while (a != b) {
            // INVESTIGATE WHY THIS GAVE ERRORS
            // a = a->next == nullptr ? headB : a->next;
            // b = b->next == nullptr ? headA : b->next;

            a = a == nullptr ? headB : a->next;
            b = b == nullptr ? headA : b->next;
        }
        return a;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    bool hasCycle(ListNode* head) {
        ListNode* slow = head;
        ListNode* fast = head;

        while (slow != NULL && fast != NULL) {
            slow = slow->next;
            fast = fast->next;

            if (fast != NULL) {
                fast = fast->next;
            } else {
                break;
            }

            if (slow == fast) {
                return true;
            }
        }
        return false;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    ListNode* detectCycle(ListNode* head) {
        if (head == nullptr || head->next == nullptr) {
            return nullptr;
        }

        auto s = head, f = head;

        while (f != nullptr && f->next != nullptr) {
            s = s->next;
            f = f->next->next;
            if (f == s) {
                break;
            }
        }
        if (s != f || f == nullptr) {
            return nullptr;
        }
        s = head;
        while (s != f) {
            s = s->next;
            f = f->next;
        }
        return f;
    }
};

class Solution {
public:
    int transform(int n) {
        int sum = 0;
        while (n > 0) {
            sum += (n % 10) * (n % 10);
            n /= 10;
        }
        return sum;
    }
    bool isHappy(int n) {
        unordered_map<int, bool> mp;
        mp[n] = true;
        while (n != 1) {
            n = transform(n);
            if (mp.contains(n) && mp[n]) {
                break;
            } else {
                mp[n] = true;
            }
        }
        return mp.contains(1) && mp[1];
    }
};

class FreqStack {
    stack<int> st;
    unordered_map<int, int> freq;
    priority_queue<int> maxf;

public:
    FreqStack() {}

    void push(int val) {
        st.push(val);
        freq[val]++;
        maxf.push(freq[val]);
    }

    int pop() {
        int f = maxf.top();
        maxf.pop();

        int ans = 0;
        stack<int> rev;
        while (!st.empty()) {
            if (freq[st.top()] == f) {
                ans = st.top();
                freq[ans]--;
                st.pop();
                break;
            } else {
                rev.push(st.top());
                st.pop();
            }
        }
        while (!rev.empty()) {
            st.push(rev.top());
            rev.pop();
        }
        return ans;
    }
};

