class Solution {
public:
    bool buddyStrings(string s, string goal) {
        int n = s.size();

        vector<int> freq(26, 0);
        bool flag = false;

        if (goal.size() != n) {
            return false;
        }
        vector<int> diff;
        int i = 0;
        while (i < n) {
            if (s[i] != goal[i]) {
                diff.push_back(i);
            }
            freq[s[i] - 'a']++;
            if (freq[s[i] - 'a'] > 1) {
                flag = true;
            }
            i++;
        }
        if (diff.size() == 0) {
            return flag;
        }
        if (diff.size() == 2) {
            int j = diff[0], k = diff[1];
            return s[j] == goal[k] && goal[j] == s[k];
        }
        return false;
    }
};

class Solution {
public:
    bool isIsomorphic(string s, string t) {
        int n = s.size();
        if(n < 2){
            return true;
        }

        unordered_map<char,char> mp1;
        unordered_map<char,char> mp2;

        for(int i = 0; i < n; i++){
            char chs = s[i];
            char cht = t[i];

            if(mp1.contains(chs) && mp1[chs] != cht){
                return false;
            }
            if(mp2.contains(cht) && mp2[cht] != chs){
                return false;
            }

            mp1[chs] = cht;
            mp2[cht] = chs;
        }

        return true;
    }
};

