};

class TimeMap {
    unordered_map<string, map<int, string>> mp;

public:
    TimeMap() {}

    void set(string key, string value, int timestamp) {
        if (!mp.contains(key)) {
            map<int, string> temp;
            mp[key] = temp;
        }
        mp[key][timestamp] = value;
    }

    string get(string key, int timestamp) {
        if (mp.contains(key) && mp[key].size() > 0) {

            auto last = mp[key].end();
            last--;
            while (last->first > timestamp) {
                last--;
                if (last == mp[key].begin()) {
                    break;
                }
            }
            return last->first <= timestamp ? last->second : "";
        }
        return "";
    }
};

