class Trie {
    struct Node {
        char ch;
        vector<Node*> next_arr;
        bool is_end;

        Node (char val){
            ch = val;
            next_arr.resize(26,nullptr);
            is_end = false;
        }
    };
    Node* root;
public:
    Trie() {
        root = new Node('*');
    }

    void insert(string word) {
        Node* temp = root;
        for(auto ch:word){
            if(temp->next_arr[ch-'a'] == nullptr){
                temp->next_arr[ch-'a'] = new Node(ch);
            }
            temp = temp->next_arr[ch-'a'];
        }
        temp->is_end = true;
    }

    bool search(string word) {
        Node* temp = root;
        for(auto ch:word){
            if(temp->next_arr[ch-'a'] == nullptr){
                return false;
            }
            temp = temp->next_arr[ch-'a'];
        }
        return temp->is_end;
    }

    bool startsWith(string prefix) {
        Node* temp = root;
        for(auto ch:prefix){
            if(temp->next_arr[ch-'a'] == nullptr){
                return false;
            }
            temp = temp->next_arr[ch-'a'];
        }
        return true;
    }
};

