class Solution {
public:
    int firstUniqChar(string s) {
        vector<int> firstIndex(26, -1);
        vector<int> counts(26, 0);
        int i = 0;
        for (auto ch : s) {
            int k = ch - 'a';
            if (firstIndex[k] < 0) {
                firstIndex[k] = i;
            }
            counts[k]++;
            i++;
        }
        int ans = s.size();
        for (i = 0; i < 26; i++) {
            if (counts[i] == 1) {
                ans = min(ans, firstIndex[i]);
            }
        }
        return ans < s.size() ? ans : -1;
    }
};

class Solution {
public:
    bool isAnagram(string s, string t) {
        unordered_map<char,int> mp;
        for(auto ch:s){
            mp[ch]++;
        }
        for(auto ch:t){
            mp[ch]--;
        }
        for(auto pr: mp){
            if(pr.second != 0){
                return false;
            }
        }
        return true;
    }
};

class Solution {
public:
    string frequencySort(string s) {
        unordered_map<char, int> freq;
        for (auto ch : s) {
            freq[ch]++;
        }
        priority_queue<pair<int, char>> pq;
        for (auto it : freq) {
            pq.push({it.second, it.first});
        }
        int i = 0;
        while (!pq.empty()) {
            int f = pq.top().first;
            char ch = pq.top().second;
            pq.pop();
            while (f > 0) {
                s[i++] = ch;
                f--;
            }
        }
        return s;
    }
};

