#define MAX_INT 100001
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<int> nodesBetweenCriticalPoints(ListNode* head) {
        vector<int> extremas;
        if (head == nullptr) {
            return {-1, -1};
        }
        int last_val = head->val, i = 1;

        vector<int> ans = {MAX_INT, -1};

        head = head->next;
        while (head->next != nullptr) {
            int val = head->val;
            int next_val = head->next->val;
            if ((last_val < val && next_val < val) ||
                (last_val > val && next_val > val)) {
                extremas.push_back(i);
                int n = extremas.size();
                if (n > 1) {
                    ans[0] = min(ans[0], extremas[n - 1] - extremas[n - 2]);
                    ans[1] = extremas[n - 1] - extremas[0];
                }
            }
            last_val = val;
            i++;
            head = head->next;
        }
        if (ans[0] == MAX_INT) {
            ans[0] = -1;
        }
        return ans;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* mergeInBetween(ListNode* list1, int a, int b, ListNode* list2) {
        auto A = list1, B = list1;
        while (a > 1) {
            a--;
            A = A->next;
        }
        while (b >= 0) {
            b--;
            B = B->next;
        }
        A->next = list2;
        while (list2->next != nullptr) {
            list2 = list2->next;
        }
        list2->next = B;
        B = nullptr;
        return list1;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* deleteDuplicates(ListNode* head) {
        ListNode* pointer = head;
        while (pointer != nullptr && pointer->next != nullptr) {
            if (pointer->val == pointer->next->val) {
                pointer->next = pointer->next->next;
            } else {
                pointer = pointer->next;
            }
        }
        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* join(vector<ListNode*> nodes) {
        ListNode* head = nullptr;
        ListNode* tail = nullptr;
        for (auto temp : nodes) {
            while (temp != nullptr) {
                if (head == nullptr) {
                    head = temp;
                } else {
                    tail->next = temp;
                }
                tail = temp;
                temp = temp->next;
            }
        }
        return head;
    }
    ListNode* reverse(ListNode* head) {
        ListNode* rev = nullptr;
        ListNode* temp = nullptr;
        while (head != nullptr) {
            temp = head;
            head = head->next;
            temp->next = rev;
            rev = temp;
        }
        return rev;
    }
    ListNode* reverseBetween(ListNode* head, int left, int right) {
        if (left == right) {
            return head;
        }

        ListNode* A = head;
        ListNode* B = head;
        ListNode* C = head;
        ListNode* temp = nullptr;

        while (right > 1) {
            C = C->next;
            right--;
        }
        temp = C;
        C = C->next;
        temp->next = nullptr;
        if (left == 1) {
            A = nullptr;
        } else {
            while (left > 2) {
                B = B->next;
                left--;
            }
            temp = B;
            B = B->next;
            temp->next = nullptr;
        }
        B = reverse(B);
        return join({A, B, C});
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<ListNode*> splitListToParts(ListNode* head, int k) {
        int n = 0;
        auto temp = head;
        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }

        vector<int> length(k, n / k);
        int extra = n % k;
        while (extra > 0) {
            length[--extra]++;
        }
        for (auto num : length) {
            cout << num << " ";
        }

        vector<ListNode*> heads(k, nullptr);
        vector<ListNode*> tails(k, nullptr);
        for (int i = 0; i < k; i++) {
            if (head == nullptr) {
                break;
            }
            while (head != nullptr && length[i] > 0) {
                temp = head;
                head = head->next;
                temp->next = nullptr;
                length[i]--;
                if (heads[i] == nullptr) {
                    heads[i] = temp;
                    tails[i] = temp;
                } else {
                    tails[i]->next = temp;
                    tails[i] = tails[i]->next;
                }
            }
        }
        return heads;
    }
};

