 */
class Solution {
public:
    int getDecimalValue(ListNode* head) {
        while (head->val == 0) {
            head = head->next;
            if (head == nullptr) {
                return 0;
            }
        }

        vector<int> arr;
        while (head != nullptr) {
            arr.push_back(head->val);
            head = head->next;
        }

        int ans = 0, n = arr.size();
        for (int i = 0; i < n; i++) {
            ans += arr[i] ? pow(2, n - 1 - i) : 0;
        }

        return ans;
    }
};

