/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        if (l1 == nullptr) {
            return l2;
        }
        if (l2 == nullptr) {
            return l1;
        }

        stack<int> s1, s2, s3;

        while (l1 != nullptr) {
            s1.push(l1->val);
            l1 = l1->next;
        }
        while (l2 != nullptr) {
            s2.push(l2->val);
            l2 = l2->next;
        }

        int sum = 0;
        while (!s1.empty() && !s2.empty()) {
            sum += s1.top();
            s1.pop();
            sum += s2.top();
            s2.pop();
            s3.push(sum % 10);
            sum /= 10;
        }
        while (!s1.empty()) {
            sum += s1.top();
            s1.pop();
            s3.push(sum % 10);
            sum /= 10;
        }
        while (!s2.empty()) {
            sum += s2.top();
            s2.pop();
            s3.push(sum % 10);
            sum /= 10;
        }
        while (sum > 0) {
            s3.push(sum % 10);
            sum /= 10;
        }
        ListNode* head = nullptr;
        ListNode* temp = nullptr;

        while (!s3.empty()) {
            ListNode* node = new ListNode(s3.top());
            s3.pop();
            if (head == nullptr) {
                head = node;
                temp = node;
            } else {
                temp->next = node;
                temp = temp->next;
            }
        }
        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* doubleIt(ListNode* head) {
        stack<int> st1, st2;
        int sum = 0;
        while (head != nullptr) {
            sum += head->val;
            head = head->next;
            st1.push(sum % 10);
            sum /= 10;
        }
        while (sum > 0) {
            st1.push(sum % 10);
            sum /= 10;
        }
        while (!st1.empty()) {
            sum += 2 * st1.top();
            st1.pop();
            st2.push(sum % 10);
            sum /= 10;
        }
        while (sum > 0) {
            st2.push(sum % 10);
            sum /= 10;
        }
        head = nullptr;
        ListNode* tail = nullptr;
        while (!st2.empty()) {
            ListNode* node = new ListNode(st2.top());
            st2.pop();
            if (head == nullptr) {
                head = node;
                tail = node;
            } else {
                tail->next = node;
                tail = tail->next;
            }
        }
        return head;
    }
};

