 */
class Solution {
public:
    ListNode* insert(ListNode* head, ListNode* node) {
        if (node->val < head->val) {
            node->next = head;
            return node;
        }
        ListNode* temp = head;
        while (temp->next != nullptr && node->val >= temp->next->val) {
            temp = temp->next;
        }
        node->next = temp->next;
        temp->next = node;
        return head;
    }
    ListNode* insertionSortList(ListNode* head) {
        ListNode* sorted = head;
        head = head->next;
        sorted->next = nullptr;
        while (head != nullptr) {
            ListNode* temp = head;
            head = head->next;
            temp->next = nullptr;
            sorted = insert(sorted, temp);
        }
        return sorted;
    }
};

