    ListNode* deleteMiddle(ListNode* head) {
        if (head == nullptr || head->next == nullptr) {
            return nullptr;
        }

        int n = 0;
        auto temp = head;
        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }
        int m = (n / 2) - 1;
        temp = head;
        while (m > 0) {
            temp = temp->next;
            m--;
        }
        auto del = temp->next;
        temp->next = temp->next->next;
        del->next = nullptr;
        return head;
    }
};

