class Solution {
public:
    ListNode* partition(ListNode* head, int x) {
        ListNode* left = nullptr;
        ListNode* right = nullptr;
        ListNode* i = nullptr;
        ListNode* j = nullptr;
        ListNode* temp = head;

        while(temp!=nullptr){
            ListNode* node = temp;
            temp = temp->next;
            node->next = nullptr;
            if(node->val < x){
                if(left == nullptr){
                    left = node;
                    i = node;
                }else{
                    i->next = node;
                    i = i->next;
                }
            }else{
                if(right == nullptr){
                    right = node;
                    j = node;
                }else{
                    j->next = node;
                    j = j->next;
                }

            }

        }
        if(i!=nullptr){
            i->next = right;
            return left;
        }
        return right;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* deleteDuplicates(ListNode* head) {

        unordered_map<int, int> freq;
        auto temp = head;
        while (temp != nullptr) {
            freq[temp->val]++;
            temp = temp->next;
        }

        while (head != nullptr && freq[head->val] > 1) {
            temp = head;
            head = head->next;
            temp->next = nullptr;
        }

        temp = head;
        while (temp != nullptr && temp->next != nullptr) {
            if (freq[temp->next->val] > 1) {
                auto dup = temp->next;
                temp->next = temp->next->next;
                dup->next = nullptr;
            } else {
                temp = temp->next;
            }
        }

        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        int n = 0;
        auto temp = head;

        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }

        if (n == 0) {
            return head;
        }

        k %= n;
        if (k == 0) {
            return head;
        }

        k = n - k - 1;
        temp = head;
        while (k > 0) {
            temp = temp->next;
            k--;
        }

        auto newhead = temp->next;
        temp->next = nullptr;

        temp = newhead;

        while (temp->next != nullptr) {
            temp = temp->next;
        }

        temp->next = head;

        return newhead;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        if(head == nullptr){
            return head;
        }

        int n = 0;
        auto temp = head;
        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }

        k = k % n;

        if (k == 0) {
            return head;
        }

        int m = n + n - k - 1, i = 0;
        temp = head;

        while (i < m) {
            temp = temp->next;
            i++;

            if (temp->next == nullptr) {
                temp->next = head;
            }
        }

        head = temp->next;
        temp->next = nullptr;

        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* swapNodes(ListNode* head, int k) {
        int n = 0;
        auto temp = head;

        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }

        auto left = head, right = head;
        int m = k - 1, p = n - k;

        while (m > 0) {
            left = left->next;
            m--;
        }

        while (p > 0) {
            right = right->next;
            p--;
        }

        int t = left->val;
        left->val = right->val;
        right->val = t;

        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverse(ListNode* head) {
        ListNode* temp = nullptr;
        while (head != nullptr) {
            auto node = head;
            head = head->next;
            node->next = temp;
            temp = node;
        }
        return temp;
    }
    int pairSum(ListNode* head) {
        auto f = head, s = head;
        while (f->next != nullptr && f->next->next != nullptr) {
            s = s->next;
            f = f->next->next;
        }
        auto left = head;
        auto right = reverse(s->next);
        int ans = 0;
        while (right != nullptr) {
            ans = max(ans, left->val + right->val);
            left = left->next;
            right = right->next;
        }
        return ans;
    }
};

class Solution {

    // k < (sqrt(8n + 1) - 1)/2

public:
    int arrangeCoins(int n) {
        long long k = n;
        double sqr = abs(sqrt(8 * k + 1));
        return floor((sqr - 1) / 2);
    }
};

class Solution {
public:
    bool isPerfectSquare(int num) {
        if (num == 1) {
            return true;
        }

        int i = 2, j = num - 1;

        while (i <= j) {

            long long k = i + (j - i) / 2;
            long long sq = k * k;

            if (sq == num) {
                return true;
            } else if (sq > num) {
                j = k - 1;
            } else {
                i = k + 1;
            }
        }
        return false;
    }
};

class Solution {
public:
    int mySqrt(int x) {
        if (x < 2) {
            return x;
        }
        int i = 1, j = x;
        while (i <= j) {
            long long k = i + (j - i) / 2;
            if (k * k <= x && (k + 1) * (k + 1) > x) {
                return k;
            } else if (k * k > x) {
                j = k - 1;
            } else {
                i = k + 1;
            }
        }
        return x;
    }
};

class Solution {
public:
    int recur(int n){
        if(n == 0){
            return 1;
        }
        if(n < 0){
            return 0;
        }
        return recur(n-1) + recur(n-2);
    }
    int memo_helper(int n, vector<int> &dp){
          if(n == 0){
            return 1;
        }
        if(n < 0){
            return 0;
        }
        if(dp[n] >= 0){
            return dp[n];
        }
        return dp[n] =  memo_helper(n-1,dp) + memo_helper(n-2,dp);
    }
    int memo(int n){
        vector<int> dp(n+1,-1);
        return memo_helper(n, dp);
    }
    int climbStairs(int n) {
        return memo(n);
    }
};

class Solution {
public:
    string convertToBase7(int num) {
        if (num == 0) {
            return "0";
        }

        bool negative = num < 0;
        num = abs(num);

        string ans = "";

        while (num > 0) {
            ans += to_string(num % 7);
            num /= 7;
        }

        if (negative) {
            ans += "-";
        }

        reverse(ans.begin(), ans.end());

        return ans;
    }
};

class Solution {
public:
    string addStrings(string num1, string num2) {
        int n = num1.size();
        int m = num2.size();
        while (n < m) {
            num1 = "0" + num1;
            n++;
        }
        while (m < n) {
            num2 = "0" + num2;
            m++;
        }
        string ans = "";
        int carry = 0;
        n--;
        while (n >= 0) {
            carry += num1[n] + num2[n] - '0' - '0';
            ans = to_string(carry % 10) + ans;
            carry /= 10;
            n--;
        }
        if (carry > 0) {
            ans = to_string(carry) + ans;
        }
        return ans;
    }
};

class Solution {
public:
    vector<string> fizzBuzz(int n) {
        vector<string> fizzBuzz;
        for(int i = 1; i <= n; i++){
            if(i%15 == 0){
                fizzBuzz.push_back("FizzBuzz");
            }
            else if(i%5 == 0){
                fizzBuzz.push_back("Buzz");
            }
            else if(i%3 == 0){
                fizzBuzz.push_back("Fizz");
            }
            else{
                fizzBuzz.push_back(to_string(i));
            }
        }

        return fizzBuzz;
    }
};

class MinStack {
    stack<pair<int, int>> st;

public:
    MinStack() {}

    void push(int value) {
        int mini;
        if (st.empty()) {
            mini = value;
        } else {
            mini = st.top().second;
        }
        mini = min(mini, value);
        st.push({value, mini});
    }

    void pop() { st.pop(); }

    int top() { return st.top().first; }

    int getMin() { return st.top().second; }
};

