class Solution {
public:
    int lengthOfLastWord(string s) {
        int n = s.size();
        int j = -1;
        int k = -1;
        int i = n-1;
        while(i >= 0){
            if(s[i] != ' '){
                j = i;
                break;
            }
            i--;
        }
        if(j == -1){
            return 0;
        }
        i = j-1;
        while(i >= 0){
            if(s[i] == ' '){
                k = i;
                break;
            }
            i--;
        }
        return j - k;
    }
};

class Solution {
public:
    string licenseKeyFormatting(string s, int k) {
        string filtered = "";
        for (auto ch : s) {
            if (isalpha(ch)) {
                filtered.push_back(toupper(ch));
            }
            if (isdigit(ch)) {
                filtered.push_back(ch);
            }
        }
        int n = filtered.size();
        if (n == 0) {
            return filtered;
        }
        int i = 0;
        string ans = "";
        while (i < n) {
            int l = n % k;
            if (i > 0) {
                ans += "-";
            }
            if (i > 0 || l == 0) {
                l = k;
            }
            ans += filtered.substr(i, l);
            i += l;
        }
        return ans;
    }
};

class WordDictionary {
    struct Node {
        char ch;
        vector<Node*> next_arr;
        bool is_end;
        Node(char val) {
            ch = val;
            next_arr.resize(26, nullptr);
            is_end = false;
        }
    };
    Node* root;

public:
    WordDictionary() { root = new Node('*'); }

    void addWord(string word) {
        Node* temp = root;
        for (auto ch : word) {
            if (temp->next_arr[ch - 'a'] == nullptr) {
                temp->next_arr[ch - 'a'] = new Node(ch);
            }
            temp = temp->next_arr[ch - 'a'];
        }
        temp->is_end = true;
    }

    bool recursive_search(string& word, int i, int n, Node* temp) {
        if (i == n) {
            return temp->is_end;
        }
        char ch = word[i];
        bool found = false;
        if (ch == '.') {
            for (Node* point : temp->next_arr) {
                if (point != nullptr) {
                    found = found || recursive_search(word, i + 1, n, point);
                }
            }
        } else {
            if (temp->next_arr[ch - 'a'] != nullptr) {
                found =
                    recursive_search(word, i + 1, n, temp->next_arr[ch - 'a']);
            }
        }
        return found;
    }

    bool search(string word) {
        int n = word.size();
        Node* temp = root;
        return recursive_search(word, 0, n, temp);
    }
};

