class Solution {
public:
    int bestClosingTime(string customers) {
        int n = customers.size();
        vector<int> No(n,0), Yes(n,0);
        int N = 0, Y = 0;

        for(int i = 0; i < n; i++){
            No[i] = N;
            if(customers[i] == 'N'){
                N++;
            }
            if(customers[n-i-1] == 'Y'){
                Y++;
            }
            Yes[n-i-1] = Y;
        }

        No.push_back(N);
        Yes.push_back(0);
        n++;

        int ans = 0, mini = No[0] + Yes[0];
        for(int i = 1; i < n; i++){
            if(mini > No[i] + Yes[i]){
                ans = i;
                mini = No[i] + Yes[i];
            }
        }
        return ans;
    }
};

class Solution {
public:
    bool isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u' ||
               ch == 'A' || ch == 'E' || ch == 'I' || ch == 'O' || ch == 'U';
    }
    string sortVowels(string s) {
        string vowel;
        for (auto ch : s) {
            if (isVowel(ch)) {
                vowel.push_back(ch);
            }
        }
        sort(vowel.begin(), vowel.end());
        int i = 0;
        for (auto &ch : s) {
            if (isVowel(ch)) {
                ch = vowel[i++];
            }
        }
        return s;
    }
};

class Solution {
public:
    string sortSentence(string s) {
        s.push_back(' ');
        int i = 0, n = s.size();
        vector<string> words(10, "");
        while (i < n) {
            int j = i;
            while (s[j] != ' ') {
                j++;
            }
            int k = s[j - 1] - '0';
            words[k] = s.substr(i, j - i - 1);
            i = j + 1;
        }

        string ans = words[1];

        for (int i = 2; i < 10; i++) {
            if (words[i].size() > 0) {
                ans += " " + words[i];
            }
        }
        return ans;
    }
};

class Solution {
public:
    string removeDuplicates(string s) {
        stack<char> st;
        for (auto ch : s) {
            if (!st.empty() && st.top() == ch) {
                st.pop();
            } else {
                st.push(ch);
            }
        }
        string ans;
        while (!st.empty()) {
            ans.push_back(st.top());
            st.pop();
        }
        reverse(ans.begin(), ans.end());

        return ans;
    }
};

class Solution {
public:
    bool isValid(string s) {
        stack<char> st;
        for (auto ch : s) {
            if (ch == '(' || ch == '{' || ch == '[') {
                st.push(ch);
            } else if (ch == ')') {
                if (!st.empty() && st.top() == '(') {
                    st.pop();
                } else {
                    return false;
                }
            } else if (ch == '}') {
                if (!st.empty() && st.top() == '{') {
                    st.pop();
                } else {
                    return false;
                }
            } else if (ch == ']') {
                if (!st.empty() && st.top() == '[') {
                    st.pop();
                } else {
                    return false;
                }
            }
        }
        return st.empty();
    }
};

class Solution {
public:
    bool rotateString(string s, string goal) {
        int n = s.size();
        int i = 0;

        while (i < n) {
            string temp = s.substr(1, n - 1);
            temp.push_back(s[0]);
            s = temp;
            if (s == goal) {
                return true;
            }
            i++;
        }
        return false;
    }
};

