class Solution {
public:
    bool isPalindrome(string s) {
        string parsed = "";
        for (auto ch : s) {
            if (isalpha(ch)) {
                parsed.push_back(tolower(ch));
            }
            if (isdigit(ch)) {
                parsed.push_back(ch);
            }
        }
        int n = parsed.size();
        if (n == 0) {
            return true;
        }
        for (int i = 0; i < n / 2; i++) {
            if (parsed[i] != parsed[n - i - 1]) {
                return false;
            }
        }
        return true;
    }
};

class Solution {
public:
    int match(string& haystack, string& needle, int i, int j){
        int k = i;
        while(k <=j){
            if(haystack[k]!=needle[k-i]){
                return -1;
            }
            k++;
        }
        return i;
    }
    int strStr(string haystack, string needle) {
        int n = haystack.size(), m = needle.size(), i = 0, j = m-1;
        while(j < n){
            if(haystack[i] == needle[0]){
                int k = match(haystack, needle, i, j);
                if(k >= 0){
                    return k;
                }
            }
            i++;
            j++;
        }
        return -1;
    }
};
